/// <summary>
/// Form datasource Active method to allowEdit for METFollowTransactionTaxItemGroup based on METIsOffRemittance
/// </summary>
/// <returns>int</returns>
int active()
{
    FormDataSource markupTableDS = this.formRun().dataSource(formDataSourceStr(MarkupTable, MarkupTable)) as FormDataSource ;
    MarkupTable markupTable = markupTableDS.cursor();

    int ret = next active();

    markupTableDS.object(fieldNum(MarkupTable, METFollowTransactionTaxItemGroup)).allowEdit(markupTable.METIsOffRemittance);

    return ret;

}
